@page "/catalog"
@using sv_2d1bfc94a8184ac198aa6b79f8adbce0.Services
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-4">Product Catalog</h3>

@if (_error is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-2" @onclick="LoadProducts">Retry</button>
    </div>
}
else
{
    <div class="row">
        <!-- Sidebar Filters -->
        <div class="col-md-3">
            <CatalogFilters Categories="_categories" OnFiltersApplied="HandleFiltersApplied" />
        </div>

        <!-- Main Content -->
        <div class="col-md-9">
            <!-- Toolbar -->
            <div class="d-flex justify-content-between align-items-center mb-3">
                <div>
                    <select class="form-select" @onchange="HandleSortChanged">
                        <option value="price_asc" selected="@(_sortBy == "price_asc")">Price: Low to High</option>
                        <option value="price_desc" selected="@(_sortBy == "price_desc")">Price: High to Low</option>
                        <option value="name_asc" selected="@(_sortBy == "name_asc")">Name: A-Z</option>
                        <option value="rating_desc" selected="@(_sortBy == "rating_desc")">Rating: Highest</option>
                    </select>
                </div>
                <div class="text-muted">
                    @if (_result is not null && _result.Items.Count > 0)
                    {
                        var start = (_result.Page - 1) * _result.PageSize + 1;
                        var end = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
                        <span>Showing @start–@end of @_result.TotalCount products</span>
                    }
                </div>
            </div>

            @if (_loading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                    <p class="mt-2">Loading products...</p>
                </div>
            }
            else if (_result is not null)
            {
                <ProductGrid Products="_result.Items"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />

                <CatalogPagination CurrentPage="_currentPage"
                                   TotalPages="_totalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        </div>
    </div>
}

@code {
    private List<string>? _categories;
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private int _pageSize = 12;
    private int _totalPages;
    private bool _loading = true;
    private string? _error;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, _pageSize);
            await Task.WhenAll(categoriesTask, productsTask);

            _categories = categoriesTask.Result;
            _result = productsTask.Result;
            _totalPages = (int)Math.Ceiling((double)_result.TotalCount / _pageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task LoadProducts()
    {
        _loading = true;
        _error = null;
        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, _pageSize);
            _totalPages = (int)Math.Ceiling((double)_result.TotalCount / _pageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        _sortBy = e.Value?.ToString() ?? "price_asc";
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for cart functionality
        return Task.CompletedTask;
    }
}

